<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
const route=useRoute(), token=String(route.params.token), contract=ref<any>(null), error=ref(''), done=ref(false), saving=ref(false)
const form=ref({signer_name:'',signer_email:'',consent:false}), canvas=ref<HTMLCanvasElement|null>(null), drawing=ref(false)
async function load(){try{contract.value=(await api<any>(`/api/contracts/sign/${token}`)).contract;form.value.signer_name=contract.value.user_name||'';form.value.signer_email=contract.value.email||''}catch(e){error.value=(e as Error).message}}
function point(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();return{x:(e.clientX-r.left)*(canvas.value!.width/r.width),y:(e.clientY-r.top)*(canvas.value!.height/r.height)}}
function start(e:PointerEvent){drawing.value=true;canvas.value!.setPointerCapture(e.pointerId);const p=point(e),c=canvas.value!.getContext('2d')!;c.beginPath();c.moveTo(p.x,p.y)}
function move(e:PointerEvent){if(!drawing.value)return;const p=point(e),c=canvas.value!.getContext('2d')!;c.lineWidth=3;c.lineCap='round';c.strokeStyle='#172554';c.lineTo(p.x,p.y);c.stroke()}
function stop(){drawing.value=false} function clear(){canvas.value!.getContext('2d')!.clearRect(0,0,canvas.value!.width,canvas.value!.height)}
async function sign(){saving.value=true;error.value='';try{await api(`/api/contracts/sign/${token}`,{method:'POST',body:JSON.stringify({...form.value,signature:canvas.value!.toDataURL('image/png')})});done.value=true}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="signing-page"><section class="signing-card" v-if="!done"><div class="brand signing-brand"><span class="brand-mark">♫</span><span>Dimensi Suara</span></div><div class="eyebrow">PENANDATANGANAN DIGITAL</div><h1>Kontrak Kerja Sama</h1><p v-if="error" class="alert error">{{ error }}</p><template v-if="contract"><div class="contract-summary"><div><small>Nama</small><strong>{{ contract.user_name }}</strong></div><div><small>Berlaku sampai</small><strong>{{ contract.expires_at }}</strong></div></div><a class="document-preview" :href="`/api/contracts/sign/${token}/document`" target="_blank">Buka dan baca dokumen kontrak ↗</a><form @submit.prevent="sign"><label>Nama lengkap<input v-model="form.signer_name" required /></label><label>Email<input v-model="form.signer_email" type="email" required /></label><label>Tanda tangan<div class="signature-wrap"><canvas ref="canvas" width="700" height="220" @pointerdown="start" @pointermove="move" @pointerup="stop" @pointercancel="stop"></canvas><button type="button" class="text-button" @click="clear">Hapus</button></div></label><label class="consent"><input v-model="form.consent" type="checkbox" required /> Saya telah membaca kontrak dan menyetujui penggunaan tanda tangan ini sebagai persetujuan digital.</label><button class="primary-button sign-button" :disabled="saving">{{ saving?'Menyimpan…':'Tandatangani Kontrak' }}</button></form></template></section><section v-else class="signing-card success-card"><div class="success-icon">✓</div><h1>Kontrak berhasil ditandatangani</h1><p>Bukti tanda tangan dan waktu persetujuan telah tersimpan.</p></section></div></template>
